chart.options:
chart: {
  type: 'streamgraph',
  height: 460
},
// Two hues, not twenty-two. With this many short-lived bands a full spectrum
// turns into confetti; splitting the palette into a warm group and a long cool
// ramp lets the eye read the shape first and pick out a band second.
colors: [
  '#E15E6C', '#D94A5E', '#C43B52',
  '#9FBEDC', '#8FB0D4', '#7FA2CC', '#6F95C5', '#6087BD',
  '#527AB5', '#456DAC', '#3C61A0', '#345693', '#2D4B86',
  '#274179', '#22386C', '#1E3060', '#1A2954', '#172248',
  '#3B4E7E', '#4A5C8C', '#5A6B9A', '#6A7AA8'
],
plotOptions: {
  streamgraph: {
    offset: 'wiggle',
    order: 'inside-out'
  }
},
legend: {
  show: false
},
title: {
  text: 'What a conference talked about',
  align: 'left'
},
subtitle: {
  text: 'Illustrative term counts, every six hours. A thread or two early, then everything at once.',
  align: 'left'
},
xaxis: {
  type: 'datetime',
  labels: {
    datetimeUTC: true,
    format: 'dd MMM'
  }
},
tooltip: {
  x: {
    format: 'dd MMM HH:mm'
  }
}
